/* Marco de las landings (el del Index, HomeIndexRebase): lienzo de 1024 centrado sobre el morado del header.
   Abierto 226 + 798 · cerrado 76 + 948. --sb lo fija el estado del sidebar. */
.root { min-height: 100vh; background: #2E0F70; }
.root, .root * { box-sizing: border-box; }
.desktopShell { --sb: 226px; display: grid; grid-template-columns: var(--sb) minmax(0, 1fr);
  grid-template-rows: 64px minmax(0, 1fr); width: min(100%, 1024px); min-width: 0; margin: 0 auto;
  transition: grid-template-columns 0.28s cubic-bezier(0.4, 0, 0.2, 1); }
.desktopShell[data-collapsed] { --sb: 76px; }
.desktopShell > header { position: sticky; top: 0; z-index: 4; grid-column: 2; grid-row: 1; }
/* La cabecera del Sidebar (logo + hamburguesa) mide 226 aunque el sidebar se cierre a 76 y va sobre el header. */
.sidebarRail { position: sticky; top: 0; z-index: 5; grid-column: 1; grid-row: 1 / -1; align-self: start; height: 100dvh; overflow: visible; }
.mainColumn { min-width: 0; grid-column: 2; grid-row: 2; background: #ffffff; }
.mobileShell { display: none; min-width: 0; overflow-x: clip; background: #fff; }
.brandLogo { display: block; width: 119px; height: 45px; object-fit: contain; }
.mobileBrand { display: inline-flex; align-items: center; gap: 10px; }
.mobileLogo { display: block; width: 96px; height: 30px; object-fit: contain; }

@media (max-width: 1023px) {
  .desktopShell { display: none; }
  .mobileShell { display: block; }
  .mobileShell, .mobileShell :global(.sbm-root), .mobileShell :global([data-block="header"]) {
    width: 100% !important; max-width: 100% !important; }
  .mobileShell > header { position: sticky; top: 0; z-index: 8; }
}

"use client";

/**
 * LandingShell — marco de las landings de VMC (Valoriza, Vendo Mis Cosas): el mismo del Index.
 * Escritorio: lienzo de 1024 con Sidebar (abierto 226, cerrado 76) y Header; el sidebar empuja al contenido.
 * Bajo 1024 px: Header con hamburguesa y el Sidebar como drawer (SidebarMobile).
 * El contenido se monta dos veces (escritorio y celular) y el CSS muestra uno; `body(id)` recibe "d" o "m"
 * para que los ids del contenido no se repitan.
 */
import { useEffect, useState } from "react";
import type { JSX, ReactNode } from "react";
import Header from "@/concorde/bloques/header/desktop/Header";
import Sidebar from "@/concorde/bloques/sidebar/desktop/Sidebar";
import SidebarMobile, { SidebarMenuButton } from "@/concorde/bloques/sidebar/mobile/SidebarMobile";
import shell from "./LandingShell.module.css";

export type LandingShellProps = {
  /** Contenido de la columna principal. */
  body: (id: "d" | "m") => ReactNode;
  /** Logo de la marca (por defecto, el de VMC del Index). */
  logoSrc?: string;
};

function BrandLogo({ className, src }: { className: string; src: string }): JSX.Element {
  return <img className={className} src={src} alt="VMC Subastas" />;
}

export default function LandingShell({ body, logoSrc = "/index/brand/logo-voyager.svg" }: LandingShellProps): JSX.Element {
  const [sidebarHeight, setSidebarHeight] = useState(900);
  const [collapsed, setCollapsed] = useState(true);
  const [menuOpen, setMenuOpen] = useState(false);
  useEffect(() => {
    const resize = () => setSidebarHeight(Math.max(720, window.innerHeight));
    resize();
    window.addEventListener("resize", resize);
    return () => window.removeEventListener("resize", resize);
  }, []);

  return (
    <div className={shell.root}>
      <div className={shell.desktopShell} data-collapsed={collapsed || undefined}>
        <Header width="100%" />
        <aside className={shell.sidebarRail} aria-label="Navegación de VMC">
          <Sidebar height={sidebarHeight} contentHeight={sidebarHeight} headerHeight={64} logo={<BrandLogo className={shell.brandLogo} src={logoSrc} />}
            collapsed={collapsed} onCollapsedChange={setCollapsed} />
        </aside>
        <main className={shell.mainColumn}>{body("d")}</main>
      </div>
      <div className={shell.mobileShell}>
        <SidebarMobile open={menuOpen} onOpenChange={setMenuOpen}>
          <Header width="100%" logo={
            <div className={shell.mobileBrand}>
              <SidebarMenuButton onClick={() => setMenuOpen(true)} expanded={menuOpen} />
              <BrandLogo className={shell.mobileLogo} src={logoSrc} />
            </div>
          } />
          {body("m")}
        </SidebarMobile>
      </div>
    </div>
  );
}

/**
 * Header — Bloque de Concorde (Voyager DS)
 *
 * Barra superior 798 × 64 con fondo vault (#2E0F70). A la derecha lleva el
 * Button «Ingresa» (variante sm-guest, con UserIcon), a 16px del borde y
 * centrado verticalmente — igual que el export de Figma (1312:4674).
 *
 * Si se pasa `username`, el CTA cambia a la variante logueada: «Bienvenido,
 * {username}» (Button sm-logged-in) — usado p.ej. en la Zona de usuario.
 */

"use client";

import type { JSX, ReactNode } from "react";
import Button, { UserIcon } from "../../../components/Button";
import { HEADER_WIDTH, HEADER_HEIGHT } from "./dimensions";

export interface HeaderProps {
  /** Ancho de la barra. Por defecto HEADER_WIDTH (798, desktop); 420 en mobile. */
  width?: number | string;
  /** Logo a la izquierda (slot). En desktop no se usa (el logo va en el Sidebar);
   *  en mobile se pasa el logo de la marca. */
  logo?: ReactNode;
  /** Usuario logueado. Si se pasa, el CTA muestra «Bienvenido, {username}»
   *  (variante sm-logged-in) en vez de «Ingresa» (sm-guest). */
  username?: string;
  /** En mobile el ancho es 420 y el botón «Bienvenido, {username}» no entra junto
   *  al logo+hamburguesa: con `compact` se muestra solo el ícono de usuario. */
  compact?: boolean;
  className?: string;
}

export default function Header({ width = HEADER_WIDTH, logo, username, compact = false, className = "" }: HeaderProps): JSX.Element {
  return (
    <header
      className={className}
      data-block="header"
      style={{
        width,
        height: HEADER_HEIGHT,
        background: "#2E0F70",
        display: "flex",
        alignItems: "center",
        justifyContent: logo ? "space-between" : "flex-end",
        padding: "0 16px",
        flexShrink: 0,
        boxSizing: "border-box",
      }}
    >
      {logo}
      {username && compact ? (
        // Solo el ícono circular (mobile) — el botón con texto no entra en 420px.
        <button
          type="button"
          aria-label={`Perfil de ${username}`}
          style={{
            width: 40,
            height: 40,
            flexShrink: 0,
            borderRadius: "50%",
            border: "2px solid rgba(255,255,255,0.7)",
            background: "linear-gradient(135deg, #ED8936 0%, #ED8936 40%, #8460E5 100%)",
            boxShadow: "rgba(255,255,255,0.28) 0 1px 0 2px inset, rgba(237,137,54,0.3) 0 2px 6px",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            color: "#ffffff",
            cursor: "pointer",
            padding: 0,
          }}
        >
          <UserIcon />
        </button>
      ) : username ? (
        <Button variant="sm-logged-in" username={username} icon={<UserIcon />} />
      ) : (
        <Button variant="sm-guest" icon={<UserIcon />}>
          Ingresa
        </Button>
      )}
    </header>
  );
}

// Button.tsx — Generado por Concorde
// Fuente: https://voyager-ds.vercel.app/preview/components/pase1
// Generado: 2026-05-25
// EDITAR LIBREMENTE después de generar

"use client";

import { forwardRef } from "react";
import type { ButtonHTMLAttributes, JSX, ReactNode } from "react";

export type ButtonVariant =
  | "primary"
  | "negotiable"
  | "secondary"
  | "secondary-sm"
  | "ghost"
  | "outline"
  | "sm-guest"
  | "sm-logged-in";

/**
 * Hereda todos los atributos nativos de <button> (type, name, className, style,
 * onMouseEnter, data-*, etc.) — basta con props, no hace falta editar el archivo.
 */
export interface ButtonProps extends ButtonHTMLAttributes<HTMLButtonElement> {
  /** Estilo visual del botón. */
  variant?: ButtonVariant;
  /** Ícono opcional en el slot circular (variantes sm-guest, secondary-sm, sm-logged-in). */
  icon?: ReactNode;
  /** Nombre de usuario — usado cuando variant="sm-logged-in". */
  username?: string;
}

// ── CSS self-contained ────────────────────────────────────────────────────

const BUTTON_STYLES = `
@property --vbtn-angle { syntax: "<angle>"; inherits: false; initial-value: 135deg; }
@property --vbtn-stop-a { syntax: "<color>"; inherits: false; initial-value: oklch(0.72 0.16 55); }
@property --vbtn-stop-b { syntax: "<color>"; inherits: false; initial-value: oklch(0.55 0.22 285); }
@property --vsec-angle { syntax: "<angle>"; inherits: false; initial-value: 160deg; }
@property --vsec-stop-a { syntax: "<color>"; inherits: false; initial-value: oklch(0.38 0.20 285); }
@property --vsec-stop-b { syntax: "<color>"; inherits: false; initial-value: oklch(0.28 0.18 285); }
@property --vneg-angle { syntax: "<angle>"; inherits: false; initial-value: 135deg; }
@property --vneg-stop-a { syntax: "<color>"; inherits: false; initial-value: #00aeb1; }
@property --vneg-stop-b { syntax: "<color>"; inherits: false; initial-value: #8460e5; }
@property --vss-angle { syntax: "<angle>"; inherits: false; initial-value: 160deg; }
@property --vss-stop-a { syntax: "<color>"; inherits: false; initial-value: #8460e5; }
@property --vss-stop-b { syntax: "<color>"; inherits: false; initial-value: #3b1782; }

/* ── primary ─────────────────────────────────────────────────────────── */
.pvbtn {
  --vbtn-stop-a: var(--vmc-color-orange-600, #ed8936);
  --vbtn-stop-b: var(--vmc-color-vault-500, #8460e5);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  height: 48px;
  padding: 0 56px;
  border-radius: var(--vmc-radius-full, 9999px);
  /* Borde GRADIENTE de Figma (1130:1778): white → #FBC47D 25% → #AE8EFF 75% → white */
  border: 2px solid transparent;
  cursor: pointer;
  position: relative;
  overflow: hidden;
  font-family: var(--vmc-font-display, "Plus Jakarta Sans", sans-serif);
  font-size: 16px;
  line-height: 20px;
  font-weight: 600;
  color: var(--vmc-color-base-white, #ffffff);
  text-shadow: rgba(0,0,0,0.25) 0 1px 3px;
  background-image:
    linear-gradient(var(--vbtn-angle), var(--vbtn-stop-a) 0%, var(--vbtn-stop-a) 40%, var(--vbtn-stop-b) 100%),
    linear-gradient(135deg, #ffffff 0%, #fbc47d 25%, #ae8eff 75%, #ffffff 100%);
  background-origin: padding-box, border-box;
  background-clip: padding-box, border-box;
  box-shadow: rgba(255,255,255,0.28) 0 1px 0 2px inset, rgba(237,137,54,0.3) 0 2px 6px;
  transition:
    --vbtn-angle 0.4s cubic-bezier(0.25, 0.8, 0.25, 1),
    --vbtn-stop-a 0.35s,
    --vbtn-stop-b 0.35s,
    transform 0.2s cubic-bezier(0.25, 0.8, 0.25, 1),
    box-shadow 0.25s;
  transform: translateZ(0);
}
.pvbtn::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: var(--vmc-radius-full, 9999px);
  background: linear-gradient(rgba(255,255,255,0.17) 0%, transparent 55%);
  pointer-events: none;
  z-index: 1;
}
.pvbtn::after {
  content: "";
  position: absolute;
  inset: -4px;
  border-radius: var(--vmc-radius-full, 9999px);
  background: linear-gradient(135deg,
    var(--vmc-color-orange-600, oklch(0.72 0.16 55)),
    var(--vmc-color-vault-500, oklch(0.55 0.22 285))
  );
  filter: blur(14px);
  opacity: 0;
  z-index: -1;
  transition: opacity 0.3s, filter 0.3s;
}
.pvbtn:hover {
  --vbtn-angle: 220deg;
  --vbtn-stop-a: var(--vmc-color-orange-400, #fbc47d);
  --vbtn-stop-b: var(--vmc-color-vault-400, #ae8eff);
  transform: translateY(-2px) scale(1.02);
  box-shadow: rgba(255,255,255,0.22) 0 1px 0 2px inset, rgba(132,96,229,0.35) 0 8px 24px, rgba(237,137,54,0.4) 0 4px 10px;
}
.pvbtn:hover::after { opacity: 0.45; filter: blur(18px); }
.pvbtn:active {
  --vbtn-angle: 135deg;
  --vbtn-stop-a: var(--vmc-color-orange-700, #d46e20);
  --vbtn-stop-b: var(--vmc-color-vault-600, #5a35c2);
  color: #d1d5dc;
  transform: scale(0.97) translateY(1px);
  box-shadow: rgba(0,0,0,0.22) 0 2px 5px 2px inset, rgba(0,0,0,0.12) 0 1px 3px;
}
.pvbtn:active::after { opacity: 0; }
.pvbtn:disabled {
  background-image: none;
  background-color: var(--vmc-color-background-disabled, #e1e3e2);
  color: var(--vmc-color-neutral-700, #99a1af);
  text-shadow: none;
  box-shadow: none;
  cursor: not-allowed;
  transform: none;
  border-color: transparent;
}
.pvbtn:disabled::after { display: none; }
.pvbtn:focus-visible {
  outline: transparent solid 3px;
  outline-offset: 4px;
  transform: scale(0.98);
  box-shadow:
    0 0 0 2px var(--vmc-color-base-white, #fff),
    0 0 0 5px var(--vmc-color-vault-500, oklch(0.55 0.22 285)),
    0 8px 16px -4px rgb(51.76% 37.65% 89.8% / 0.30);
}

/* ── secondary ───────────────────────────────────────────────────────── */
.psec {
  --vsec-stop-a: var(--vmc-color-vault-500, #8460e5);
  --vsec-stop-b: var(--vmc-color-vault-700, #3b1782);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  height: 48px;
  padding: 0 56px;
  border-radius: var(--vmc-radius-full, 9999px);
  /* Borde GRADIENTE lila de Figma (1133:2294): #CFBAFF → white 35% → #AE8EFF 65% → #CFBAFF */
  border: 2px solid transparent;
  cursor: pointer;
  position: relative;
  overflow: hidden;
  font-family: var(--vmc-font-display, "Plus Jakarta Sans", sans-serif);
  font-size: 16px;
  line-height: 20px;
  font-weight: 600;
  color: var(--vmc-color-base-white, #ffffff);
  text-shadow: rgba(0,0,0,0.3) 0 1px 3px;
  background-image:
    linear-gradient(var(--vsec-angle), var(--vsec-stop-a) 0%, var(--vsec-stop-b) 100%),
    linear-gradient(135deg, #cfbaff 0%, #ffffff 35%, #ae8eff 65%, #cfbaff 100%);
  background-origin: padding-box, border-box;
  background-clip: padding-box, border-box;
  box-shadow: rgba(255,255,255,0.22) 0 1px 0 2px inset, rgba(132,96,229,0.3) 0 2px 8px;
  transition:
    --vsec-angle 0.4s cubic-bezier(0.25, 0.8, 0.25, 1),
    --vsec-stop-a 0.35s,
    --vsec-stop-b 0.35s,
    transform 0.2s cubic-bezier(0.25, 0.8, 0.25, 1),
    box-shadow 0.25s;
  transform: translateZ(0);
}
.psec::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: var(--vmc-radius-full, 9999px);
  background: linear-gradient(rgba(255,255,255,0.15) 0%, transparent 55%);
  pointer-events: none;
  z-index: 1;
}
.psec::after {
  content: "";
  position: absolute;
  inset: -4px;
  border-radius: var(--vmc-radius-full, 9999px);
  background: linear-gradient(135deg,
    var(--vmc-color-vault-500, oklch(0.55 0.22 285)),
    var(--vmc-color-vault-700, oklch(0.38 0.20 285))
  );
  filter: blur(14px);
  opacity: 0;
  z-index: -1;
  transition: opacity 0.3s, filter 0.3s;
}
.psec:hover {
  --vsec-angle: 219deg;
  --vsec-stop-a: var(--vmc-color-vault-400, #ae8eff);
  --vsec-stop-b: var(--vmc-color-vault-600, #5a35c2);
  transform: translateY(-2px) scale(1.02);
  box-shadow: rgba(255,255,255,0.2) 0 1px 0 2px inset, rgba(132,96,229,0.4) 0 8px 24px, rgba(132,96,229,0.25) 0 4px 10px;
}
.psec:hover::after { opacity: 0.45; filter: blur(18px); }
.psec:active {
  --vsec-angle: 160deg;
  --vsec-stop-a: var(--vmc-color-vault-700, #3b1782);
  --vsec-stop-b: var(--vmc-color-vault-900, #22005c);
  color: #d1d5dc;
  transform: scale(0.97) translateY(1px);
  box-shadow: rgba(0,0,0,0.28) 0 2px 5px 2px inset, rgba(0,0,0,0.14) 0 1px 3px;
}
.psec:active::after { opacity: 0; }
.psec:disabled {
  background-image: none;
  background-color: var(--vmc-color-background-disabled, #e1e3e2);
  color: var(--vmc-color-neutral-700, #99a1af);
  text-shadow: none;
  box-shadow: none;
  cursor: not-allowed;
  transform: none;
  border-color: transparent;
}
.psec:disabled::after { display: none; }
.psec:focus-visible {
  outline: transparent solid 3px;
  outline-offset: 4px;
  transform: scale(0.98);
  box-shadow:
    0 0 0 2px var(--vmc-color-base-white, #fff),
    0 0 0 5px var(--vmc-color-vault-500, oklch(0.55 0.22 285)),
    0 8px 16px -4px rgb(51.76% 37.65% 89.8% / 0.30);
}

/* ── ghost · "Ver Ofertas relacionadas" ─────────────────────────────────
   Sync SVG Figma (1143:1709/1885/1909): frame 215×48 con texto casi al
   borde → padding 12px (antes 28px). Estados ya coincidían exacto. */
.pghost {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  height: 48px;
  padding: 0 12px;
  border-radius: var(--vmc-radius-full, 9999px);
  border: 2px solid rgba(255,255,255,0.75);
  cursor: pointer;
  position: relative;
  overflow: hidden;
  font-family: var(--vmc-font-display, "Plus Jakarta Sans", sans-serif);
  font-size: 16px;
  line-height: 20px;
  font-weight: 600;
  color: var(--vmc-color-base-white, #ffffff);
  background: transparent;
  text-shadow: rgba(0,0,0,0.18) 0 1px 3px;
  box-shadow: rgba(255,255,255,0.2) 0 1px 0 2px inset, rgba(255,255,255,0.15) 0 0 0 1px;
  transition:
    background 0.25s,
    border-color 0.25s,
    color 0.25s,
    transform 0.2s cubic-bezier(0.25, 0.8, 0.25, 1),
    box-shadow 0.25s;
  transform: translateZ(0);
}
.pghost::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: var(--vmc-radius-full, 9999px);
  background: linear-gradient(rgba(255,255,255,0.1) 0%, transparent 55%);
  pointer-events: none;
  z-index: 1;
}
.pghost::after {
  content: "";
  position: absolute;
  inset: -4px;
  border-radius: var(--vmc-radius-full, 9999px);
  background: linear-gradient(135deg,
    var(--vmc-color-orange-600, oklch(0.72 0.16 55)),
    var(--vmc-color-vault-500, oklch(0.55 0.22 285))
  );
  filter: blur(16px);
  opacity: 0;
  z-index: -1;
  transition: opacity 0.3s, filter 0.3s;
}
.pghost:hover {
  background: linear-gradient(146.64deg, #fff 0%, rgb(255,240,226) 100%);
  border-color: #fff;
  color: #ed8936;
  text-shadow: rgba(0,0,0,0.25) 0 1px 3px;
  transform: translateY(-2px) scale(1.02);
  box-shadow: rgba(255,255,255,0.5) 0 1px 0 2px inset, rgba(0,0,0,0.2) 0 6px 20px;
}
.pghost:hover::after { opacity: 0.4; filter: blur(18px); }
.pghost:active {
  background: linear-gradient(146.56deg, rgb(212,110,32) 0%, rgb(183,55,0) 100%);
  border-color: #d46e20;
  color: var(--vmc-color-icon-disabled, #e1e3e2);
  text-shadow: rgba(0,0,0,0.25) 0 1px 3px;
  transform: scale(0.97) translateY(1px);
  box-shadow: rgba(0,0,0,0.22) 0 2px 5px 2px inset;
}
.pghost:active::after { opacity: 0; }
.pghost:disabled {
  /* SVG Ghost/Disabled (1153:2443): borde white 0.3, glass white 0.1→transparent, texto white 0.35 */
  background: linear-gradient(rgba(255,255,255,0.1) 0%, transparent 55%);
  border: 2px solid rgba(255,255,255,0.3);
  color: rgba(255,255,255,0.35);
  text-shadow: none;
  box-shadow: none;
  cursor: not-allowed;
  transform: none;
}
.pghost:focus-visible {
  outline: transparent solid 3px;
  outline-offset: 4px;
  transform: scale(0.98);
  box-shadow:
    0 0 0 2px var(--vmc-color-base-white, #fff),
    0 0 0 5px var(--vmc-color-vault-500, oklch(0.55 0.22 285)),
    0 8px 16px -4px rgb(51.76% 37.65% 89.8% / 0.30);
}

/* ── sm-guest ─────────────────────────────────────────────────────────── */
.pvbtn-sm {
  --vbtn-stop-a: var(--vmc-color-orange-600, #ed8936);
  --vbtn-stop-b: var(--vmc-color-vault-500, #8460e5);
  display: inline-flex;
  align-items: center;
  gap: 8px;
  height: 40px;
  min-width: 116px;
  padding: 0 16px 0 4px;
  border-radius: var(--vmc-radius-full, 9999px);
  /* Borde GRADIENTE de Figma (1159:4466): white → #FBC47D 25% → #AE8EFF 75% → white */
  border: 2px solid transparent;
  cursor: pointer;
  position: relative;
  overflow: hidden;
  font-family: var(--vmc-font-display, "Plus Jakarta Sans", sans-serif);
  font-size: 14px;
  line-height: 16px;
  font-weight: 600;
  color: var(--vmc-color-base-white, #ffffff);
  text-shadow: rgba(0,0,0,0.2) 0 1px 2px;
  background-image:
    linear-gradient(var(--vbtn-angle), var(--vbtn-stop-a) 0%, var(--vbtn-stop-a) 40%, var(--vbtn-stop-b) 100%),
    linear-gradient(135deg, #ffffff 0%, #fbc47d 25%, #ae8eff 75%, #ffffff 100%);
  background-origin: padding-box, border-box;
  background-clip: padding-box, border-box;
  box-shadow: rgba(255,255,255,0.25) 0 1px 0 2px inset, rgba(237,137,54,0.25) 0 2px 6px;
  transition:
    --vbtn-angle 0.4s cubic-bezier(0.25, 0.8, 0.25, 1),
